    printf 'M%d\n' "$1"
}

gen_params() {
    local i
    local hdr=""
    local call=""
    for ((i = 1; i <= $1; i++)); do
        hdr="$hdr${hdr:+,}&P$i"
        call="$call${call:+,}$i"
    done
    printf 'MACRO PM %s\n add r0,&P%d\nMEND\nPM %s\n' "$hdr" "$1" "$call"
}

