#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
ROOT_DIR="$(dirname "$SCRIPT_DIR")"
CC24="$ROOT_DIR/components/cli/target/release/tc24r"
DEMO_C="$SCRIPT_DIR/demo13.c"
DEMO_S="$SCRIPT_DIR/demo13.s"
if [ ! -f "$CC24" ]; then cargo build --manifest-path "$ROOT_DIR/components/cli/Cargo.toml" --release --quiet; fi

echo "=== tc24r Demo 13: break/continue ==="
"$CC24" "$DEMO_C" -o "$DEMO_S"
LGO=$(mktemp --suffix=.lgo)
cor24-asm "$DEMO_S" -o "$LGO"
OUTPUT=$(cor24-emu --lgo "$LGO" --dump --speed 0 --time 10 2>&1)
rm -f "$LGO"
echo "$OUTPUT"
echo ""
R0=$(echo "$OUTPUT" | grep "r0:" | head -1 | awk -F'[()]' '{print $2}' | tr -d ' ')
HALTED=$(echo "$OUTPUT" | grep "Halted:" | head -1 | awk '{print $2}')
UART=$(echo "$OUTPUT" | grep "UART TX log:" | awk -F'UART TX log:' '{print $2}' | tr -d ' "')
echo "=== Validation ==="
PASS=true
if [ "$HALTED" = "true" ]; then echo "  [PASS] CPU halted"; else echo "  [FAIL] no halt"; PASS=false; fi
if [ "$R0" = "42" ]; then echo "  [PASS] r0 = 42"; else echo "  [FAIL] r0 = $R0"; PASS=false; fi
if echo "$UART" | grep -q "D13OK"; then echo "  [PASS] UART: D13OK"; else echo "  [FAIL] UART: '$UART'"; PASS=false; fi
echo ""
if [ "$PASS" = true ]; then echo "Demo 13 PASSED"; else echo "Demo 13 FAILED"; exit 1; fi
// tc24r demo13 -- break and continue
//
// New features:
//   - break: exits innermost loop
//   - continue: jumps to loop increment/condition
//   - Works in while, do...while, and for loops
//
// Expected: r0 = 42, UART output: "D13OK"

#define UART_DATA   0xFF0100
#define UART_STATUS 0xFF0101
void putc(int c) { while (*(char *)UART_STATUS & 0x80) {} *(char *)UART_DATA = c; }
void puts(char *s) { while (*s) { putc(*s); s = s + 1; } }

int main() {
    int ok = 1;

    // break in while
    int i = 0;
    while (1) {
        if (i == 5) { break; }
        i = i + 1;
    }
    if (i != 5) { ok = 0; }

    // continue in while (sum odd numbers 1-9)
    int sum = 0;
    int j = 0;
    while (j < 10) {
        j = j + 1;
        if (j % 2 == 0) { continue; }
        sum = sum + j;
    }
    if (sum != 25) { ok = 0; }

    // break in for
    int k = 0;
    for (k = 0; k < 100; k = k + 1) {
        if (k == 3) { break; }
    }
    if (k != 3) { ok = 0; }

    // continue in for (skip evens)
    int total = 0;
    for (int n = 1; n <= 5; n = n + 1) {
        if (n % 2 == 0) { continue; }
        total = total + n;
    }
    if (total != 9) { ok = 0; }

    if (ok) {
        puts("D13OK\n");
        return 42;
    }
    return 0;
}
void putc(int c) { *(char *)0xFF0100 = c; }
void puts(const char *s) { while (*s) { putc(*s); s = s + 1; } }

